import { join } from "node:path";
import BetterSqlite3 from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { CamelCasePlugin, Kysely, SqliteDialect } from "kysely";
import { z } from "zod";

import type { Database } from "better-sqlite3";
import type { DB } from "./kysely-types.ts";

/** Generated by `pnpm db:generate`; resolved from this file so tests, `pnpm dev` and the container agree. */
export const MIGRATIONS_DIR = join(import.meta.dirname, "..", "..", "drizzle");

export interface Db {
  sqlite: Database;
  kysely: Kysely<DB>;
}

export function openDatabase(path: string): Db {
  const sqlite = new BetterSqlite3(path);
  sqlite.pragma("busy_timeout = 5000");
  if (path !== ":memory:") sqlite.pragma("journal_mode = WAL");
  // Migrations run inside a transaction, where `PRAGMA foreign_keys` is a no-op, so enforcement
  // is switched off here, outside it. Table rebuilds would otherwise fire ON DELETE actions.
  sqlite.pragma("foreign_keys = OFF");
  migrate(drizzle(sqlite), { migrationsFolder: MIGRATIONS_DIR });
  const broken = sqlite.prepare("PRAGMA foreign_key_check").all();
  if (broken.length > 0) {
    sqlite.close();
    throw new Error("The database has rows that break a foreign key after migrating.");
  }
  sqlite.pragma("foreign_keys = ON");
  // Queries use the schema's camelCase names; the plugin maps them to the snake_case columns.
  const kysely = new Kysely<DB>({
    dialect: new SqliteDialect({ database: sqlite }),
    plugins: [new CamelCasePlugin()],
  });
  return { sqlite, kysely };
}

export async function closeDatabase(db: Db): Promise<void> {
  await db.kysely.destroy();
  // Kysely only closes the handle once it has run a query.
  if (db.sqlite.open) db.sqlite.close();
}

/**
 * Deletes every row the bot stores, in one transaction, keeping the schema and its migration
 * history. Tables are listed from the database itself, so a new table is covered without a change.
 */
export function clearData(db: Db): void {
  const tables = z
    .array(z.string())
    .parse(
      db.sqlite
        .prepare(
          "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name != '__drizzle_migrations'",
        )
        .pluck()
        .all(),
    );
  db.sqlite.transaction(() => {
    // Foreign keys are checked at commit, when every table is empty, so the order doesn't matter.
    db.sqlite.pragma("defer_foreign_keys = ON");
    for (const table of tables) db.sqlite.prepare(`DELETE FROM "${table}"`).run();
  })();
  // DELETE only marks pages free, so the rows could still be read from the file. VACUUM rewrites
  // the file with live data only, and the checkpoint empties the WAL, which held the old pages too.
  db.sqlite.exec("VACUUM");
  db.sqlite.pragma("wal_checkpoint(TRUNCATE)");
}
